const material=(T,c,extra={})=>new T.MeshStandardMaterial({color:c,roughness:.35,metalness:.02,...extra});
function box(g,T,x,y,z,sx,sy,sz,c,name,selected){let m=new T.Mesh(new T.BoxGeometry(sx,sy,sz),material(T,c));m.position.set(x,y,z);m.name=name;g.add(m);if(selected===name){let e=new T.LineSegments(new T.EdgesGeometry(m.geometry),new T.LineBasicMaterial({color:0xffedcc}));e.position.copy(m.position);g.add(e);}return m;}
function sphere(g,T,x,y,z,r,c,sx=1,sy=1,sz=1){let m=new T.Mesh(new T.SphereGeometry(r,28,20),material(T,c));m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m;}
function line(g,T,pts,color,r=.04){let curve=new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(...p)));let m=new T.Mesh(new T.TubeGeometry(curve,32,r,12,false),material(T,color));g.add(m);return m;}
export function buildLeaf(g,T,w={}){let e=Number(w.explode??.2),sel=w.part||'all';for(let row=0;row<2;row++)for(let col=0;col<5;col++)box(g,T,-1.6+col*.8,1.12+e,row*.75-.4,.77,.18,.72,0xc3cbb8,'epidermis',sel);for(let row=0;row<2;row++)for(let col=0;col<6;col++){let x=-1.65+col*.65,z=row*.65-.35;box(g,T,x,.5+e*.3,z,.58,.8,.58,0x8ca99c,'palisade',sel);for(let k=0;k<3;k++)sphere(g,T,x-.18+k*.17,.64,z+.3,.075,0x446e60,.7,1.3,.55);}for(let i=0;i<12;i++){let x=-1.7+(i%4)*1.03,y=-.45-(i%2)*.24-e*.2,z=Math.floor(i/4)*.58-.5;let m=sphere(g,T,x,y,z,.33,sel==='spongy'?0xc4d6ba:0x91aaa1,1.2,.6,.8);m.name='spongy';}box(g,T,0,-1.23-e,0,4.1,.15,1.5,0xb8c4b4,'epidermis',sel);for(let i=0;i<2;i++){let tube=new T.Mesh(new T.CylinderGeometry(.12,.12,3.9,24),material(T,i?0xd18c7c:0x7dabb9));tube.rotation.z=Math.PI/2;tube.position.set(0,-.54+i*.26,.85);tube.name=i?'phloem':'xylem';g.add(tube);if(sel===tube.name){let rim=new T.Mesh(new T.CylinderGeometry(.15,.15,3.95,24,1,true),new T.MeshBasicMaterial({color:0xffedcc,wireframe:true}));rim.rotation.copy(tube.rotation);rim.position.copy(tube.position);g.add(rim);}}for(let sign of[-1,1])sphere(g,T,sign*.22,-1.34-e,.84,.22,sel==='guard'?0xe5c397:0x789c87,.65,.45,1.6);}
export function buildRoot(g,T,w={}){const long=w.hair!=='short';let cell=new T.Mesh(new T.CapsuleGeometry(.62,1.6,12,32),material(T,0xc0b49b,{transparent:true,opacity:.72}));cell.rotation.z=Math.PI/2;g.add(cell);line(g,T,[[.65,.1,0],[1.15,.25,0],[long?2.1:1.4,.45,0]],0xd4bd9b,long?.17:.22);sphere(g,T,-.8,0,.4,.2,0x9b6e65);for(let i=0;i<6;i++)sphere(g,T,-.75+i*.25,-.25,.42,.08,0xc79175,1.4,.65,.7);const result=w.result||'in',count=w.kind==='ions'?7:11;for(let i=0;i<count;i++){let moved=w.revealed&&result==='in',x=moved?.35+(i%3)*.25:1.8+(i%3)*.28,y=-.7+Math.floor(i/3)*.36;sphere(g,T,x,y,.25,.065,w.kind==='ions'?0xe6b681:0x85b5c5);}if(w.revealed&&result==='out')for(let i=0;i<7;i++)sphere(g,T,1.8+(i%2)*.3,-.7+i*.2,.25,.06,0x85b5c5);}
export function buildTube(g,T,w={}){let phloem=w.tissue==='phloem',ri=phloem?.54:.6,ro=.76,shape=new T.Shape(),a=Math.PI*5/6,b=Math.PI*13/6;shape.absarc(0,0,ro,a,b,false);shape.lineTo(Math.cos(b)*ri,Math.sin(b)*ri);shape.absarc(0,0,ri,b,a,true);shape.closePath();let wall=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:3.8,bevelEnabled:false,curveSegments:48}),material(T,phloem?0xd0a296:0xbca287,{side:T.DoubleSide}));wall.rotation.x=Math.PI/2;wall.position.y=1.9;wall.name='tube-wall';g.add(wall);if(!phloem&&w.lignin!==false)for(let i=0;i<8;i++){let ring=new T.Mesh(new T.TorusGeometry(.77,.035,10,48,Math.PI*4/3),material(T,0x927465));ring.rotation.x=Math.PI/2;ring.rotation.z=Math.PI*5/6;ring.position.y=-1.6+i*.46;g.add(ring);}if(phloem)for(let y of[-.65,.65]){let plate=new T.Shape();plate.absarc(0,0,.55,0,Math.PI*2,false);for(let i=0;i<7;i++){let angle=i*Math.PI*2/6,r=i===6?0:.32,hole=new T.Path();hole.absarc(Math.cos(angle)*r,Math.sin(angle)*r,.07,0,Math.PI*2,true);plate.holes.push(hole);}let m=new T.Mesh(new T.ExtrudeGeometry(plate,{depth:.045,bevelEnabled:false,curveSegments:24}),material(T,0xe7bcaa,{side:T.DoubleSide}));m.rotation.x=Math.PI/2;m.position.y=y;m.name='porous-end-wall';g.add(m);}for(let i=0;i<9;i++)sphere(g,T,Math.sin(i*2)*.23,-1.55+i*.38,Math.cos(i*2)*.2,.075,phloem?0xecc08b:0x82aebb);const arrow=new T.Mesh(new T.ConeGeometry(.13,.28,24),material(T,phloem?0xecc08b:0x82aebb));arrow.rotation.z=w.direction==='down'?Math.PI:0;arrow.position.set(0,w.direction==='down'?-1.3:1.3,.5);arrow.name='transport-direction';g.add(arrow);}
export function buildStoma(g,T,w={}){let open=w.open!==false,gap=open?.28:.015;const baseShape=new T.Shape();baseShape.moveTo(-1.9,-1.3);baseShape.lineTo(1.9,-1.3);baseShape.lineTo(1.9,1.3);baseShape.lineTo(-1.9,1.3);baseShape.closePath();const pore=new T.Path();pore.absellipse(0,0,open?.48:.015,.8,0,Math.PI*2,true);baseShape.holes.push(pore);const base=new T.Mesh(new T.ExtrudeGeometry(baseShape,{depth:.13,bevelEnabled:false}),material(T,0xa9b9a9));base.position.z=-.3;base.name='epidermis-with-pore';g.add(base);for(let sign of[-1,1]){const s=new T.Shape();s.moveTo(sign*gap,-.92);s.bezierCurveTo(sign*(gap+.98),-1.2,sign*(gap+1.15),1.12,sign*gap,.92);s.bezierCurveTo(sign*(gap+(open?.38:.015)),.45,sign*(gap+(open?.38:.015)),-.45,sign*gap,-.92);let m=new T.Mesh(new T.ExtrudeGeometry(s,{depth:.25,bevelEnabled:true,bevelThickness:.05,bevelSize:.05,bevelSegments:3,curveSegments:36}),material(T,0x769e8b,{side:T.DoubleSide}));m.name='guard-cell';g.add(m);for(let i=0;i<5;i++)sphere(g,T,sign*(gap+.6),-.65+i*.32,.32,.085,0x3f6c5c,1,.6,.7);}for(let i=0;i<(w.emission??(open?7:2));i++)sphere(g,T,-.9+i*.27,1.25+(i%2)*.25,.2,.065,0x86b6c7);}
export function buildWhole(g,T,w={}){line(g,T,[[0,-1.3,0],[0,0,0],[0,1.6,0]],0x91a78d,.12);for(let sign of[-1,1]){line(g,T,[[0,-1.3,0],[sign*.5,-1.6,0],[sign*1.25,-1.85,.1]],0xc0a58a,.07);let leaf=sphere(g,T,sign*.8,.65,.02,.65,0x90b09a,1.4,.35,.65);leaf.rotation.z=sign*.4;line(g,T,[[0,.15,0],[sign*.4,.4,0],[sign*.8,.65,0]],0x678c7b,.045);}sphere(g,T,0,1.65,0,.16,w.tip==='shoot'?0xf2cf9b:0xabc0a3);for(let sign of[-1,1])sphere(g,T,sign*1.25,-1.85,.1,.12,w.tip==='root'?0xf2cf9b:0xc8af91);let up=w.direction!=='down';for(let i=0;i<6;i++)sphere(g,T,.18,-1.05+i*.42,.25,.07,up?0x8bb8c9:0xe5b18a);}
